41	/**
42	 * semantic_vad eagerness — how soon the model ends the user's turn. "low" lets
43	 * the user take their time (fewer spurious interruptions); "high" chunks ASAP;
44	 * "auto" === "medium".
45	 */
46	export type VadEagerness = "low" | "medium" | "high" | "auto";
47	
48	/**
49	 * Remote MCP tool, executed by the Realtime API itself (not by this client).
50	 * The client's only jobs are configuring access here and answering approval
51	 * requests if `require_approval` asks for them.
52	 */
53	export interface McpToolConfig {
54	  type: "mcp";
55	  /** Unique label for this server within the session's tools array. */
56	  server_label: string;
57	  server_url: string;
58	  /** OAuth access token (or other bearer credential) for the MCP server. */
59	  authorization?: string;
60	  /** Narrow the imported tool surface — the server sees any data the model sends. */
61	  allowed_tools?: string[];
62	  require_approval?: "always" | "never";
63	  // NOTE: the docs also list `server_description`, but gpt-realtime-2 rejects
64	  // it ("Unknown parameter") — don't add it back without checking the model.
65	}
66	
67	/** Classic function tool — the app executes it and returns function_call_output. */
68	export interface FunctionToolConfig {
69	  type: "function";
70	  name: string;
71	  description: string;
72	  parameters: Record<string, unknown>;
73	}
74	
75	export type RealtimeToolConfig = McpToolConfig | FunctionToolConfig;
76	
77	export interface OpenaiAgentConfig {
78	  /** Realtime model for the session + token mint. */
79	  model: string;
80	  /** One of OpenAI's built-in voices. Locked after the first audio output. */
81	  voice: OpenaiVoice;
82	  /** System prompt sent in `session.update` → `session.instructions`. */
83	  instructions: string;
84	  /** Prompt that elicits the agent's opening line (sent as a user item + response.create). */
85	  firstMessage: string;
86	  /** Reasoning effort sent as `session.reasoning.effort`. */
87	  reasoningEffort: ReasoningEffort;
88	  /** Input-audio transcription so the UI can show the user's words. */
89	  transcription: {
90	    /** Streaming transcription model — `gpt-realtime-whisper` for realtime. */
91	    model: string;
92	    /** Optional language hint such as "en". */
93	    language?: string;
94	    /** Latency/accuracy tradeoff for gpt-realtime-whisper. */
95	    delay?: TranscriptionDelay;
96	  };
97	  /** Tools enabled for the session. Empty by default. */
98	  tools: RealtimeToolConfig[];
99	  /**
100	   * Turn-taking strategy, passed straight through to
101	   * `session.audio.input.turn_detection`. We use `semantic_vad` (ends a turn
102	   * when the user has *semantically* finished, so background noise and fillers
103	   * don't trigger a turn); `server_vad` (energy + `threshold`) is still
104	   * expressible for tuning either way.
105	   */
106	  turnDetection: {
107	    type: "server_vad" | "semantic_vad";
108	    /** semantic_vad: how eagerly to end the user's turn ("low" lets them finish). */
109	    eagerness?: VadEagerness;
110	    /** server_vad: activation threshold 0.0–1.0; higher needs louder speech (less sensitive). */
111	    threshold?: number;
112	    /** server_vad: silence (ms) before the server ends the user's turn. */
113	    silence_duration_ms?: number;
114	    /** Audio kept before detected speech start, so first words aren't clipped. */
115	    prefix_padding_ms?: number;
116	    /** Auto-create a response after each user turn (conversation-only; default true). */
117	    create_response?: boolean;
118	    /** Let user speech interrupt the agent / barge-in (conversation-only; default true). */
119	    interrupt_response?: boolean;

1	# Tool use with Live API
2	
3	Tool use allows Live API to go beyond just conversation by enabling it to
4	perform actions in the real-world and pull in external context while maintaining
5	a real time connection.
6	You can define tools such as [Function calling](https://ai.google.dev/gemini-api/docs/function-calling)
7	and [Google Search](https://ai.google.dev/gemini-api/docs/grounding) with the Live API.
8	
9	## Overview of supported tools
10	
11	Here's a brief overview of the available tools for Live API models:
12	
13	| Tool | Gemini 3.1 Flash Live Preview | Gemini 2.5 Flash Live Preview |
14	|---|---|---|
15	| **Search** | Supported | Supported |
16	| **Function calling** | Supported (synchronous only) | Supported (synchronous and [asynchronous](https://ai.google.dev/gemini-api/docs/live-api/tools#async-function-calling)) |
17	| **Google Maps** | Not supported | Not supported |
18	| **Code execution** | Not supported | Not supported |
19	| **URL context** | Not supported | Not supported |
20	
21	## Function calling
22	
23	Live API supports function calling, just like regular content generation
24	requests. Function calling lets the Live API interact with external data and
25	programs, greatly increasing what your applications can accomplish.
26	
27	You can define function declarations as part of the session configuration.
28	After receiving tool calls, the client should respond with a list of
29	`FunctionResponse` objects using the `session.send_tool_response` method.
30	
31	See the [Function calling tutorial](https://ai.google.dev/gemini-api/docs/function-calling) to learn
32	more.
33	
34	> [!NOTE]
35	> **Note:** Unlike the `generateContent` API, the Live API doesn't support automatic tool response handling. You must handle tool responses manually in your client code.
36	
37	### Python
38	
39	    import asyncio
40	    import wave
41	    from google import genai
42	    from google.genai import types
43	
44	    client = genai.Client()
45	
46	    model = "gemini-3.1-flash-live-preview"
47	
48	    # Simple function definitions
49	    turn_on_the_lights = {"name": "turn_on_the_lights"}
50	    turn_off_the_lights = {"name": "turn_off_the_lights"}
51	
52	    tools = [{"function_declarations": [turn_on_the_lights, turn_off_the_lights]}]
53	    config = {"response_modalities": ["AUDIO"], "tools": tools}
54	
55	    async def main():
56	        async with client.aio.live.connect(model=model, config=config) as session:
57	            prompt = "Turn on the lights please"
58	            await session.send_client_content(turns={"parts": [{"text": prompt}]})
59	
60	            wf = wave.open("audio.wav", "wb")
61	            wf.setnchannels(1)
62	            wf.setsampwidth(2)
63	            wf.setframerate(24000)  # Output is 24kHz
64	
65	            async for response in session.receive():
66	                if response.data is not None:
67	                    wf.writeframes(response.data)
68	                elif response.tool_call:
69	                    print("The tool was called")
70	                    function_responses = []
71	                    for fc in response.tool_call.function_calls:
72	                        function_response = types.FunctionResponse(
73	                            id=fc.id,
74	                            name=fc.name,
75	                            response={ "result": "ok" } # simple, hard-coded function response
76	                        )
77	                        function_responses.append(function_response)
78	
79	                    await session.send_tool_response(function_responses=function_responses)
80	
81	            wf.close()
82	
83	    if __name__ == "__main__":
84	        asyncio.run(main())
