1	// Mints a short-lived Gemini Live ephemeral auth token server-side so the
2	// browser can open a WebSocket to Google WITHOUT ever seeing GEMINI_API_KEY.
3	//
4	// Flow: client POSTs here → we call the v1alpha auth-token service via
5	// @google/genai → return { token }. The browser then connects with
6	//   wss://…/v1alpha.GenerativeService.BidiGenerateContentConstrained?access_token=<token>
7	//
8	// Unlike the xAI/OpenAI mint routes (plain fetch), Google documents no raw REST
9	// endpoint for token creation — only the SDK — so this route uses @google/genai.
10	// The token is UNCONSTRAINED (no liveConnectConstraints): persona config stays
11	// client-side in lib/realtime/gemini-agent.ts, mirroring the xAI engine.
12	//
13	// Dev only: GEMINI_API_KEY is provided via fnox (`fnox exec -- bun run dev`).
14	
15	import { GoogleGenAI } from "@google/genai";
16	
17	export const runtime = "nodejs";
18	// Never cache a freshly-minted token.
19	export const dynamic = "force-dynamic";
20	
21	// Single-use token: one CALL press = one mint = one Live session.
22	const TOKEN_TTL_MINUTES = 30;
23	const NEW_SESSION_WINDOW_MINUTES = 1;
24	
25	export async function POST(): Promise<Response> {
26	  const apiKey = process.env.GEMINI_API_KEY;
27	  if (!apiKey) {
28	    // Do not echo any key material; just say it's unset.
29	    return Response.json(
30	      { error: "GEMINI_API_KEY is not set on the server (provide it via fnox)." },
31	      { status: 500 },
32	    );
33	  }
34	
35	  // Ephemeral tokens are v1alpha-only (SDK: "Support in v1alpha only").
36	  const ai = new GoogleGenAI({ apiKey, httpOptions: { apiVersion: "v1alpha" } });
37	  const now = Date.now();
38	
39	  try {
40	    const token = await ai.authTokens.create({
41	      config: {
42	        uses: 1,
43	        expireTime: new Date(now + TOKEN_TTL_MINUTES * 60_000).toISOString(),
44	        newSessionExpireTime: new Date(now + NEW_SESSION_WINDOW_MINUTES * 60_000).toISOString(),
45	      },
46	    });
47	    if (!token.name) {
48	      return Response.json({ error: "Gemini returned a token without a name." }, { status: 502 });
49	    }
50	    return Response.json({ token: token.name }, { headers: { "Cache-Control": "no-store" } });
51	  } catch (err) {
52	    return Response.json(
53	      {
54	        error: `Gemini auth-token mint failed: ${err instanceof Error ? err.message : "unknown error"}`,
55	      },
56	      { status: 502 },
57	    );
58	  }
59	}
